const makeItem = (id: string, keterangan: string, qty: number, satuan: string, hargaUnit: number, disc = 0) => {
  const total = qty * hargaUnit;
  const hargaJual = total * (1 - disc / 100);
  return { id, keterangan, subKeterangan: '', qty, satuan, hargaUnit, total, disc, hargaJual };
};

